@@ -25,4 +25,51 @@
 </div>
 <div class="touch-controls" aria-label="Touch driving controls"><div class="touch-group"><div class="touch-wrap"><button class="touch-btn" data-control="left">◀</button><div class="touch-label">STEER</div></div><div class="touch-wrap"><button class="touch-btn" data-control="right">▶</button></div></div><div class="touch-group"><div class="touch-wrap"><button class="touch-btn brake" data-control="brake">▼</button><div class="touch-label">BRAKE</div></div><div class="touch-wrap"><button class="touch-btn gas" data-control="gas">▲</button><div class="touch-label">THROTTLE</div></div></div></div>
 <div class="overlay" id="overlay"><section class="card"><div class="eyebrow" id="eyebrow">NO RULES. NO BRAKES. NO MERCY.</div><h1 id="title">WRECKING<br><span>CREW</span></h1><p id="desc">The arena is yours. Slam rival rides into the wall, send them spinning, and be the last car still moving.</p><div class="rules" id="rules"><div class="rule"><b>01 · RAM</b><span>Build speed before impact</span></div><div class="rule"><b>02 · SURVIVE</b><span>Keep your ride in one piece</span></div><div class="rule"><b>03 · DOMINATE</b><span>Wreck 5 rivals in 90 seconds</span></div></div><button class="primary" id="startBtn">ENTER THE ARENA</button><div class="footer-note" id="footer">WASD / ARROWS TO DRIVE · SPACE TO DRIFT</div></section></div>
 <script>
+(()=>{
+const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');
+const $=id=>document.getElementById(id);
+const ui={overlay:$('overlay'),start:$('startBtn'),title:$('title'),desc:$('desc'),eyebrow:$('eyebrow'),rules:$('rules'),footer:$('footer'),clock:$('clock'),wrecks:$('wrecks'),health:$('healthbar'),healthNum:$('healthNum'),hits:$('hits'),best:$('besthit'),feed:$('feed'),toast:$('toast'),pause:$('pauseBtn')};
+const W=1200,H=760,arena={l:112,r:1088,t:96,b:664};
+let dpr=1,screenW=0,screenH=0,gameState='menu',last=0,elapsed=0,timeLeft=90,player,opponents=[],cars=[],particles=[],debris=[],impactCount=0,bestImpact=0,toastTimer=0,feedTimer=0,shake=0;
+const input={left:false,right:false,gas:false,brake:false,hand:false};
+const colors=['#f45c39','#4ed5ca','#e9c34d','#b480f5','#7fd264','#f282b1'];
+const names=['BULLDOG','SLEDGE','GHOST','RUSTY','VOLT','MAYHEM'];
+function resize(){dpr=Math.min(devicePixelRatio||1,2);screenW=innerWidth;screenH=innerHeight;canvas.width=Math.round(screenW*dpr);canvas.height=Math.round(screenH*dpr)}
+addEventListener('resize',resize);resize();
+function makeCar(i,x,y,a){return {id:i,player:i===0,x,y,vx:0,vy:0,angle:a,hp:100,color:colors[i],name:names[i],r:23,speed:0,steer:0,cooldown:0,hitFlash:0,alive:true,aiThink:Math.random()*1.5,stun:0,trail:[]}}
+function resetGame(){elapsed=0;timeLeft=90;impactCount=0;bestImpact=0;particles=[];debris=[];shake=0;player=makeCar(0,600,555,-Math.PI/2);opponents=[makeCar(1,340,245,Math.PI/2),makeCar(2,860,230,Math.PI),makeCar(3,950,485,-2.5),makeCar(4,340,475,.3),makeCar(5,600,180,Math.PI/2)];cars=[player,...opponents];gameState='playing';ui.overlay.classList.add('hidden');ui.pause.textContent='Ⅱ';ui.feed.innerHTML='Engines hot. Make some noise.';toast('FIGHT!');updateHud()}
+function showOverlay(kind){ui.overlay.classList.remove('hidden');if(kind==='pause'){ui.eyebrow.textContent='TAKE A BREATHER';ui.title.innerHTML='DERBY<br><span>PAUSED</span>';ui.desc.textContent='The arena can wait. Your rivals definitely cannot.';ui.rules.style.display='none';ui.start.textContent='BACK TO THE ACTION';ui.footer.textContent='PRESS P OR ESC TO RESUME';}
+else if(kind==='result'){const won=player.hp>0;ui.eyebrow.textContent=won?'ARENA CHAMPION':'TOTALLED';ui.title.innerHTML=won?'DEMOLITION<br><span>ROYALTY</span>':'OUT OF<br><span>COMMISSION</span>';ui.desc.innerHTML=`${won?'You own the pit.':'The pit claimed another one.'} You wrecked <b>${opponents.filter(c=>!c.alive).length}</b> rival${opponents.filter(c=>!c.alive).length===1?'':'s'} and landed <b>${impactCount}</b> impacts.`;ui.rules.style.display='none';ui.start.textContent='RUN IT BACK';ui.footer.textContent=`BEST HIT ${bestImpact} KM/H · ${localStorage.getItem('derby-best')||0} CAREER WRECKS`;}
+else{ui.eyebrow.textContent='NO RULES. NO BRAKES. NO MERCY.';ui.title.innerHTML='WRECKING<br><span>CREW</span>';ui.desc.textContent='The arena is yours. Slam rival rides into the wall, send them spinning, and be the last car still moving.';ui.rules.style.display='flex';ui.start.textContent='ENTER THE ARENA';ui.footer.textContent='WASD / ARROWS TO DRIVE · SPACE TO DRIFT';}}
+function pause(){if(gameState==='playing'){gameState='paused';showOverlay('pause');ui.pause.textContent='▶'}else if(gameState==='paused'){gameState='playing';ui.overlay.classList.add('hidden');ui.pause.textContent='Ⅱ';last=performance.now()}}
+ui.start.addEventListener('click',()=>{if(gameState==='paused'){gameState='playing';ui.overlay.classList.add('hidden');ui.pause.textContent='Ⅱ';last=performance.now()}else resetGame()});
+ui.pause.addEventListener('click',pause);
+addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='w'||k==='arrowup')input.gas=true;if(k==='s'||k==='arrowdown')input.brake=true;if(k==='a'||k==='arrowleft')input.left=true;if(k==='d'||k==='arrowright')input.right=true;if(k===' ')input.hand=true;if((k==='p'||k==='escape')&&(gameState==='playing'||gameState==='paused'))pause()});
+addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k==='w'||k==='arrowup')input.gas=false;if(k==='s'||k==='arrowdown')input.brake=false;if(k==='a'||k==='arrowleft')input.left=false;if(k==='d'||k==='arrowright')input.right=false;if(k===' ')input.hand=false});
+document.querySelectorAll('.touch-btn').forEach(btn=>{const key=btn.dataset.control,down=e=>{e.preventDefault();input[key]=true;btn.classList.add('down');btn.setPointerCapture?.(e.pointerId)},up=e=>{e.preventDefault();input[key]=false;btn.classList.remove('down')};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('lostpointercapture',up)});
+function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.15}
+function setFeed(text){ui.feed.innerHTML=text;feedTimer=3.1}
+function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
+function normAngle(a){while(a>Math.PI)a-=Math.PI*2;while(a<-Math.PI)a+=Math.PI*2;return a}
+function addParticle(x,y,color,n=5,power=100){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=Math.random()*power;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.55,max:.8,size:2+Math.random()*4,color})}}
+function wreck(c,attacker){c.hp=0;c.alive=false;c.vx*=.25;c.vy*=.25;c.stun=999;addParticle(c.x,c.y,'#ffb04e',32,210);addParticle(c.x,c.y,'#545d60',20,120);shake=12;toast(c.player?'WRECKED!':'WRECK!');setFeed(c.player?'Your ride is <em>TOTALLED</em>.':`<em>${attacker?.name||'RIVAL'}</em> wrecked ${c.name}!`);if(!c.player){let count=+(localStorage.getItem('derby-best')||0);localStorage.setItem('derby-best',String(count+1))}}
+function update(dt){if(gameState!=='playing')return;elapsed+=dt;timeLeft=Math.max(0,90-elapsed);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}if(feedTimer>0)feedTimer-=dt;
+for(const c of cars){if(!c.alive)continue;c.cooldown=Math.max(0,c.cooldown-dt);c.hitFlash=Math.max(0,c.hitFlash-dt);let throttle=0,steer=0,hand=false;
+if(c.player){throttle=(input.gas?1:0)-(input.brake?1:0);steer=(input.right?1:0)-(input.left?1:0);hand=input.hand}
+else{c.aiThink-=dt;if(c.aiThink<=0){c.aiThink=.3+Math.random()*.35;c.target=player.alive?player:opponents.find(o=>o.alive&&o!==c)}const target=c.target&&c.target.alive?c.target:player;const tx=target?.x??600,ty=target?.y??380;const desired=Math.atan2(ty-c.y,tx-c.x);let diff=normAngle(desired-c.angle);const d=Math.hypot(tx-c.x,ty-c.y);if(d<115)diff=normAngle(diff+(Math.sin(elapsed*3+c.id)*.7));steer=clamp(diff*1.65,-1,1);throttle=d<65?.35:1;hand=Math.abs(diff)>1.65&&Math.hypot(c.vx,c.vy)>170}
+const speed=Math.hypot(c.vx,c.vy),direction=speed<5?1:Math.sign(c.vx*Math.cos(c.angle)+c.vy*Math.sin(c.angle));c.angle+=steer*(.9+Math.min(speed/180,1.35))*(hand?1.12:1)*direction*dt;
+if(throttle>0){c.vx+=Math.cos(c.angle)*430*throttle*dt;c.vy+=Math.sin(c.angle)*430*throttle*dt}else if(throttle<0){c.vx-=Math.cos(c.angle)*280*(-throttle)*dt;c.vy-=Math.sin(c.angle)*280*(-throttle)*dt}
+const max=c.player?350:270;const drag=hand?1.9:0.62;c.vx*=Math.exp(-drag*dt);c.vy*=Math.exp(-drag*dt);
+// Tire grip softly pulls velocity toward the car's facing direction, with extra slip under handbrake.
+const forward=c.vx*Math.cos(c.angle)+c.vy*Math.sin(c.angle),side=-c.vx*Math.sin(c.angle)+c.vy*Math.cos(c.angle),grip=hand?.9:4.7;const side2=side*Math.exp(-grip*dt);c.vx=Math.cos(c.angle)*forward-Math.sin(c.angle)*side2;c.vy=Math.sin(c.angle)*forward+Math.cos(c.angle)*side2;
+const sp=Math.hypot(c.vx,c.vy);if(sp>max){c.vx*=max/sp;c.vy*=max/sp}c.speed=sp;c.x+=c.vx*dt;c.y+=c.vy*dt;
+if(c.x<arena.l+c.r){c.x=arena.l+c.r;c.vx=Math.abs(c.vx)*.58;wallHit(c)}if(c.x>arena.r-c.r){c.x=arena.r-c.r;c.vx=-Math.abs(c.vx)*.58;wallHit(c)}if(c.y<arena.t+c.r){c.y=arena.t+c.r;c.vy=Math.abs(c.vy)*.58;wallHit(c)}if(c.y>arena.b-c.r){c.y=arena.b-c.r;c.vy=-Math.abs(c.vy)*.58;wallHit(c)}
+if(c.speed>135&&Math.random()<dt*2.7)addParticle(c.x-Math.cos(c.angle)*22,c.y-Math.sin(c.angle)*22,'#697579',1,27);
+}
+// Soft bumper collisions. Contact impulse creates a satisfying shove and damage scales with impact speed.
+for(let i=0;i<cars.length;i++){const a=cars[i];if(!a.alive)continue;for(let j=i+1;j<cars.length;j++){const b=cars[j];if(!b.alive)continue;let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy),min=a.r+b.r;if(d>=min)continue;if(d<.01){dx=1;dy=0;d=1}const nx=dx/d,ny=dy/d,over=min-d;a.x-=nx*over*.51;a.y-=ny*over*.51;b.x+=nx*over*.51;b.y+=ny*over*.51;const rel=(b.vx-a.vx)*nx+(b.vy-a.vy)*ny;if(rel<0){const impulse=-(1.26*rel)/2;a.vx-=nx*impulse;a.vy-=ny*impulse;b.vx+=nx*impulse;b.vy+=ny*impulse;const impact=Math.abs(rel);if(impact>42&&(a.cooldown<=0||b.cooldown<=0)){const dmg=clamp((impact-28)*.075,2,24);for(const c of [a,b]){c.hp-=dmg*(c.player?.8:1);c.hitFlash=.2;c.cooldown=.42}if(a.player||b.player){impactCount++;bestImpact=Math.max(bestImpact,Math.round(impact));shake=Math.min(10,impact*.025);addParticle((a.x+b.x)/2,(a.y+b.y)/2,'#ffd56a',Math.ceil(dmg/2),impact*.6);if(impact>115)toast(impact>230?'MONSTER HIT!':'BIG HIT!');setFeed(`${a.player?'<em>YOU</em>':a.name} slammed ${b.player?'<em>YOU</em>':b.name} · <em>${Math.round(impact)} KM/H</em>`)}if(a.hp<=0)wreck(a,b);if(b.hp<=0)wreck(b,a)}}}}
+for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.exp(-2.2*dt);p.vy*=Math.exp(-2.2*dt);p.life-=dt}particles=particles.filter(p=>p.life>0);shake*=Math.exp(-8*dt);
+if(player.hp<=0){gameState='result';showOverlay('result')}else if(timeLeft<=0||opponents.every(c=>!c.alive)){gameState='result';showOverlay('result')}updateHud()}
+function wallHit(c){if(c.speed>110&&c.cooldown<=0){c.hp-=Math.min(11,(c.speed-90)*.03);c.cooldown=.52;c.hitFlash=.15;if(c.player){impactCount++;bestImpact=Math.max(bestImpact,Math.round(c.speed*.58));setFeed('Wall kiss · <em>WATCH YOUR LINES</em>');addParticle(c.x,c.y,'#f8a64d',5,90)}if(c.hp<=0)wreck(c)}}
+function updateHud(){ui.clock.textContent=`${String(Math.floor(timeLeft/60)).padStart(2,'0')}:${String(Math.ceil(timeLeft%60)).padStart(2,'0')}`;ui.wrecks.textContent=`${opponents.filter(c=>!c.alive).length} / 5`;const hp=clamp(player?.hp??100,0,100);ui.health.style.width=hp+'%';ui.health.style.background=hp<30?'linear-gradient(90deg,#eb273d,#ff703a)':'linear-gradient(90deg,#ff4c34,#ffb33f)';ui.healthNum.textContent=Math.ceil(hp)+'%';ui.hits.textContent=impactCount;ui.best.textContent=bestImpact}

