function roundRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function draw(){const sx=screenW/W,sy=screenH/H;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,screenW,screenH);const bg=ctx.createLinearGradient(0,0,screenW,screenH);bg.addColorStop(0,'#1b2529');bg.addColorStop(.55,'#11191d');bg.addColorStop(1,'#080d10');ctx.fillStyle=bg;ctx.fillRect(0,0,screenW,screenH);ctx.setTransform(dpr*sx,0,0,dpr*sy,0,0);ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);
// Arena shadow and tire-darkened perimeter
