(145deg,#172126ed,#101619ed);box-shadow:0 25px 100px #0009;position:relative;overflow:hidden}.card:before{content:"";position:absolute;top:0;left:0;width:72px;height:3px;background:var(--orange);box-shadow:0 0 22px var(--orange)}.eyebrow{font-size:10px;letter-spacing:.25em;color:var(--cyan);font-weight:800}.card h1{font-size:clamp(38px,9vw,67px);line-height:.88;letter-spacing:-.055em;font-style:italic;margin:16px 0 12px;text-transform:uppercase}.card h1 span{color:var(--orange)}.card p{color:#b6c0bf;font-size:13px;line-height:1.55;margin:0 0 20px}.rules{display:flex;gap:8px;margin:18px 0 24px}.rule{flex:1;background:#ffffff08;border:1px solid #ffffff13;border-radius:10px;padding:11px 9px}.rule b{display:block;font-size:11px;color:#f6f1e7}.rule span{font-size:9px;color:#a9b4b8}.primary{width:100%;border:0;border-radius:10px;padding:15px 18px;background:var(--orange);color:#171717;font-size:13px;font-weight:1000;letter-spacing:.18em;text-transform:uppercase;cursor:pointer;box-shadow:0 8px 24px #ff64343b;transition:transform .15s,filter .15s}.primary:hover{filter:brightness(1.12);transform:translateY(-2px)}.footer-note{text-align:center;color:#8f9b9b;font-size:9px;letter-spacing:.13em;margin-top:14px}.result{font-size:14px!important;color:#f2eee5!important}.touch-controls{display:none;pointer-events:none;position:fixed;inset:auto 0 max(18px,env(safe-area-inset-bottom)) 0;height:145px;justify-content:space-between;align-items:flex-end;padding:0 20px}.touch-group{display:flex;gap:10px;align-items:flex-end}.touch-btn{pointer-events:auto;width:62px;height:62px;border-radius:50%;background:#162126ad;border:1px solid #e8f4ec4d;color:#eef3ea;font-size:19px;font-weight:800;backdrop-filter:blur(7px);touch-action:none}.touch-btn.gas{width:72px;height:72px;background:#ff6434bb;border-color:#ffb093}.touch-btn.brake{width:60px;height:60px;color:#ffb49a}.touch-btn:active,.touch-btn.down{transform:scale(.94);background:#5ee7dbbb}.touch-label{text-align:center;color:#dbe4dc;font-size:8px;letter-spacing:.1em;margin-top:4px}.touch-wrap{display:flex;flex-direction:column;align-items:center}
